package net.battlespades.session;
import java.util.*;
import java.util.function.*;
import net.battlespades.bot.BotMessages.Objective;
import net.battlespades.bot.BotState.Cell;
import net.battlespades.match.ObjectiveZone;
import net.battlespades.physics.PlayerPhysics.Vector;

/** Mode-sanctioned strategic facts. Hidden enemy positions enter only through publicly carried objectives. */
public final class HostedBotObjectives {
    private final Thread owner=Thread.currentThread();private final StandardMatchDomain match;private final Supplier<List<Objective>> horde,refuge;private final Map<String,Double> failures=new HashMap<>();
    public HostedBotObjectives(StandardMatchDomain match,Supplier<List<Objective>> horde,Supplier<List<Objective>> refuge){this.match=Objects.requireNonNull(match);this.horde=Objects.requireNonNull(horde);this.refuge=Objects.requireNonNull(refuge);}
    private void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Bot objectives outside owner");}
    public String phase(){owned();if(match.demolition().isPresent())return match.demolition().orElseThrow().phase().name().toLowerCase(Locale.ROOT);if(match.vip().isPresent())return match.vip().orElseThrow().phase().name().toLowerCase(Locale.ROOT);if(match.zombie().isPresent())return match.zombie().orElseThrow().phase().name().toLowerCase(Locale.ROOT);return "";}
    public List<Objective> snapshot(){owned();var out=new ArrayList<Objective>();block(out,"mh_hill",this::hills);block(out,"tc_territory",this::territories);block(out,"dia",this::diamonds);block(out,"oc",this::occupation);block(out,"dem_base",this::demolition);block(out,"ctf",this::ctf);block(out,"team_anchor",this::anchors);block(out,"zombie_refuge",refuge);block(out,"zombie_order",horde);block(out,"vip",this::vips);block(out,"last_survivor",this::last);return List.copyOf(out);}
    private void block(List<Objective> out,String name,Supplier<List<Objective>> action){try{out.addAll(action.get());}catch(RuntimeException failure){double now=match.monotonic();if(now-failures.getOrDefault(name,Double.NEGATIVE_INFINITY)>=60){failures.put(name,now);match.failure("bot objective "+name,failure);}}}
    private static Objective objective(String kind,int team,Vector at,int carrier,int state,List<Integer> bounds,List<Cell> cells,List<Cell> repair,double progress,int attacker,double expires){return new Objective(kind,team,at,carrier,state,bounds,cells,repair,progress,attacker,expires);}
    static Objective simple(String kind,int team,Vector at,int carrier,int state){return objective(kind,team,at,carrier,state,List.of(),List.of(),List.of(),0,-1,-1);}
    private static List<Integer> bounds(ObjectiveZone z){return List.of(z.x0(),z.x1(),z.y0(),z.y1(),z.z0(),z.z1());}
    private List<Objective> hills(){if(!match.baseCode().equals("mh"))return List.of();var runtime=match.zones().orElseThrow();double expires=runtime.rotationAt()>0?Math.max(0,runtime.rotationAt()-match.wall()):-1;return runtime.states().stream().map(h->objective("mh_hill",h.owner()==2||h.owner()==3?h.owner():1,h.zone().center(),-1,h.contested()?1:0,bounds(h.zone()),List.of(),List.of(),0,-1,expires)).toList();}
    private List<Objective> territories(){if(!match.baseCode().equals("tc"))return List.of();return match.zones().orElseThrow().states().stream().map(h->objective("tc_territory",h.owner()==2||h.owner()==3?h.owner():1,h.zone().center(),-1,h.contested()?1:0,List.of(),List.of(),List.of(),h.progress(),h.attacker()==2||h.attacker()==3?h.attacker():-1,-1)).toList();}
    private List<Objective> diamonds(){if(!(match.carry().orElse(null) instanceof HostedDiamondRuntime runtime))return List.of();var out=new ArrayList<Objective>();for(var b:runtime.bases())if(b.active())out.add(simple("dia_dropoff",b.team()==2||b.team()==3?b.team():1,b.zone().center(),-1,Math.max(0,b.remaining())));for(var d:runtime.ground())out.add(simple("dia_diamond",1,d.position(),-1,0));for(var p:match.lives().players())if(runtime.carrying(p))out.add(simple("dia_diamond",p.team(),p.position(),p.id(),1));return out;}
    private List<Objective> occupation(){if(!(match.carry().orElse(null) instanceof HostedOccupationRuntime runtime))return List.of();var out=new ArrayList<Objective>();var target=runtime.target();if(target!=null)out.add(objective("oc_target",3,target.center(),-1,0,bounds(target),List.of(),List.of(),0,-1,-1));for(var bomb:runtime.states()){var carrier=bomb.carrier();out.add(simple("oc_bomb",carrier==null?1:carrier.team(),carrier==null?bomb.position():carrier.position(),carrier==null?-1:carrier.id(),bomb.armed()?1:0));}return out;}
    private List<Objective> demolition(){if(match.demolition().isEmpty())return List.of();var runtime=match.demolition().orElseThrow();var out=new ArrayList<Objective>();for(int team:new int[]{2,3}){var hint=runtime.botHints(team);if(hint.zone()==null)continue;out.add(objective("dem_base",team,hint.zone().center(),-1,hint.damage(),hint.wholeVolume()?bounds(hint.zone()):List.of(),hint.cells().stream().map(c->new Cell(c.x(),c.y(),c.z())).toList(),hint.repair().stream().map(c->new Cell(c.x(),c.y(),c.z())).toList(),0,-1,-1));}return out;}
    private List<Objective> ctf(){if(match.ctf().isEmpty())return List.of();var runtime=match.ctf().orElseThrow();var out=new ArrayList<Objective>();for(int team:new int[]{2,3}){var intel=runtime.state(team);if(intel.base()!=null)out.add(simple("ctf_base",team,intel.base(),-1,0));var holder=intel.holder();var at=holder==null?intel.position():holder.position();if(at!=null)out.add(simple("ctf_intel",team,at,holder==null?-1:holder.id(),holder!=null?2:intel.dropped()>0?1:0));}return out;}
    private List<Objective> anchors(){var out=new ArrayList<Objective>();for(int team:new int[]{2,3})try{out.add(simple("team_anchor",team,match.teamAnchor(team),-1,0));}catch(IllegalArgumentException|IllegalStateException failure){/* One unavailable authored anchor does not erase the other. */}return out;}
    private List<Objective> vips(){if(match.vip().isEmpty())return List.of();var runtime=match.vip().orElseThrow();var out=new ArrayList<Objective>();for(int team:new int[]{2,3})runtime.vip(team).filter(p->p.alive()&&p.spawned()&&runtime.liveVip(p)).ifPresent(p->out.add(simple("vip",team,p.position(),p.id(),0)));return out;}
    private List<Objective> last(){if(match.zombie().isEmpty())return List.of();return match.zombie().orElseThrow().lastSurvivor().map(p->List.of(simple("last_survivor",p.team(),p.position(),p.id(),0))).orElse(List.of());}
}
